  The SV of SingleStringCharacter :: LineContinuation is the empty code unit sequence.
---*/

// LineTerminatorSequence :: <LF>
assert.sameValue('\
', '');

// LineTerminatorSequence :: <CR> [lookahead ≠ <LF>]
assert.sameValue('\', '');

// LineTerminatorSequence :: <LS>
