assert.sameValue('\ ', '');

// LineTerminatorSequence :: <PS>
// <PS> is U+2029 PARAGRAPH SEPARATOR; UTF8(0x2029) = 0xE2 0x80 0xA9
assert.sameValue('\ ', '');

// LineTerminatorSequence :: <CR> <LF>
assert.sameValue('\
', '');

